use std::path::Path;
fn main(){let a:Vec<_>=std::env::args().collect();let result=if a.len()==6&&a[1]=="__guardian"{let fds=a[2..].iter().map(|s|s.parse::<i32>()).collect::<Result<Vec<_>,_>>();fds.map_err(|_|uasf_queue::error("descriptors")).and_then(|f|uasf_queue::guardian::run(f[0],f[1],f[2],f[3]))}else if a.len()==4&&a[2]=="--config"{uasf_queue::config::load(Path::new(&a[3])).and_then(|c|match a[1].as_str(){"bind"=>c.bind(),"unbind"=>c.unbind(),"serve"=>uasf_queue::server::serve(c),_=>Err(uasf_queue::error("arguments"))})}else{Err(uasf_queue::error("arguments"))};if let Err(e)=result{eprintln!("{e}");std::process::exit(2);}}
